const buildAugust13Sections = (detail: typeof aug13ResearchDetails[string], evidence: string) => [
  { heading: 'Methodology and scope', body: [`This report studies ${detail.unit}. The research question is ${detail.question}. The unit is deliberately narrower than an entire platform because distributed development is easier to evaluate when the boundary is observable: a request, record, message, or job has a beginning, a result, and an owner. We synthesize NIST, OWASP, W3C, IETF, and vendor documentation where it is directly relevant, then translate those sources into observations a buyer-side engineering lead can request from a Philippines-based developer. This is not a claim that location determines technical quality. It is an evidence model for work whose review may happen across time zones. The analysis distinguishes a technical fact, a product assumption, and a decision that still requires the internal owner.`] },
  { heading: 'What the evidence can establish', body: [`For this topic, the most useful measures are ${detail.measures}. They should be collected over a named cohort or period, not reported as an impression. A useful sample might cover 100 representative records, 30 days of endpoint traffic, or every supported client class; the right denominator depends on the system. The evidence should include both successful and rejected cases, because a control that only demonstrates the happy path says little about its boundary. It should also retain the input conditions: schema version, identity type, dataset watermark, device state, or release revision. Without those conditions, two developers can produce apparently different results while testing different systems. A reviewer can then ask whether the sample represents the real users and whether the measured failure class matters to the service.`] },
  { heading: 'Finding: boundaries matter more than activity', body: [`The central finding is that ${detail.failure} is more informative than a count of tickets closed or tests run. A bounded assignment should name the inputs, the permitted side effects, the expected output, and the cases that stop the work for review. For ${detail.unit}, that means showing normal behavior, malformed or adversarial input, an interruption, and the recovery or disclosure path. NIST Secure Software Development Framework guidance supports integrating security practices into the lifecycle; OWASP verification guidance similarly emphasizes testable requirements rather than vague confidence. The practical implication is modest but important: ask for a small, reviewable proof that the boundary holds. Do not treat a polished demo, a green aggregate, or a copied vendor example as evidence that the local implementation preserves the same assumptions.`] },
  { heading: 'Cohorts, units, and measurement design', body: [`Measurement should be designed before implementation. Define the population, the observation window, and the exclusion rule. For example, a pagination study can separate records changed during traversal from records that were stable; a rate-limit study can separate authenticated identities from shared networks; an offline-sync study can separate non-conflicting edits from concurrent edits. Report counts and denominators together, then preserve a few representative traces with sensitive values removed. A single percentage can hide a severe tail, so inspect the worst cases and the cases that crossed a boundary. If the system has no trustworthy baseline, record that limitation instead of inventing one. The developer can prepare fixtures and queries, but the internal owner must decide which cohort represents acceptable product behavior and which error warrants a pause.`] },
  { heading: 'Implementation implications for a distributed team', body: [`A good assignment begins with a short technical brief that names the source of truth, the affected route or component, and the reviewer who can answer domain questions. It should state what access is needed and what access is explicitly out of scope. The developer then supplies a focused change, reproducible verification, and a note about behavior not covered. For ${detail.unit}, the review should compare the implementation against ${detail.decision}, not merely against a task title. Written examples reduce ambiguity when the reviewer is offline, while a small overlap window is useful for unresolved decisions rather than for supervising every keystroke. Durable evidence should use stable identifiers and explicit timestamps. Architecture changes, security exceptions, production permissions, and acceptance of residual risk remain with the client-side owner.`] },
  { heading: 'Failure modes and counterevidence', body: [`The strongest report makes room for counterevidence. Look for cases where the control passes under one identity but fails under another, works for a small dataset but degrades at a boundary, or behaves correctly until a retry, timeout, or concurrent mutation occurs. Also examine observability: can the team tell the difference between a rejected input, a missing record, a stale read, and an internal failure? A control may be technically present yet operationally weak if nobody can detect its failure or explain its scope. The reviewer should request at least one negative fixture and one interruption or recovery trace. If the result changes after a dependency, browser, device, or schema revision, record that revision. This is not an argument for exhaustive testing; it is an argument for choosing failure cases that map to the stated risk.`] },
  { heading: 'Bounded interpretation', body: [`These findings support better scoping, not a universal performance promise. Standards describe desirable properties, but they do not guarantee that a particular implementation, team, or product satisfies them. The evidence may be biased toward documented systems and may miss behavior outside the observed cohort. Reviewer capacity can also become the limiting factor: a perfect report that nobody can read or act on is not a useful control. The recommendation is therefore to pilot the evidence model on one representative slice, compare the observed result with the product owner’s threshold, and revise the brief when assumptions are wrong. Keep unresolved questions visible. A distributed developer can expose uncertainty early, but the person accountable for the product must decide whether the remaining risk is acceptable, whether more evidence is required, or whether the scope should stop.`] },
  { heading: 'Operational evidence and handoff', body: [`The handoff should be a compact record, not a transcript of effort. Include the change identifier, the environment or fixture used, the cohort and observation window, the commands or queries that produced the result, and links to the relevant source guidance. State which cases were not exercised and why. For ${detail.unit}, preserve one successful trace and one boundary trace with secrets and personal data removed. If a retry, migration, export, or synchronization remains in flight, show its current state and the condition that will close it. The receiving owner should be able to reproduce the material claim within a reasonable review session, challenge an assumption without searching through private messages, and identify the exact decision that still belongs to them. This format makes asynchronous collaboration more reliable while keeping accountability with the person who owns the product outcome.`] },
  { heading: 'Conclusion and decision record', body: [`For ${detail.unit}, a publication-ready conclusion should answer four questions: what was observed, for which cohort or period, which authoritative sources support the interpretation, and what decision follows. The conclusion should name the accepted behavior, the known limit, and the next owner. If the evidence is incomplete, say exactly what is missing instead of converting absence into confidence. This approach helps a client evaluate an offshore developer on technical judgment and communication as well as implementation speed. It also keeps the work aligned with DeveloperOffshore.com’s real service: a defined software-development lane with access boundaries, reviewable outcomes, and responsible ownership. The result is a decision record that another engineer can reproduce, challenge, or extend without relying on a private conversation.`] },
];

const aug17IndependentBodies: Record<string, readonly { heading: string; body: readonly string[] }[]> = {
  'offshore-developer-review-latency-research-2026-08-17': [{ heading: 'Research question and scope', body: ['This report asks whether a distributed pull-request queue protects review quality or merely delays work. The unit is one change with a known risk class, review timestamps, revision history, and post-merge finding. GitHub review guidance and Google code-review practice support small, reviewable changes, but neither source sets an acceptable waiting time. The question is local: which changes need prompt attention, and which can wait without losing context?'] }, { heading: 'Method and measurement', body: ['Measure queue age, time to first substantive review, revision cycles, change size, risk category, and findings after merge. Separate author delay from reviewer delay. A median can hide security-sensitive changes that wait longest. Compare similar changes over a named period and preserve abandoned requests. The handoff should show whether a Philippines-based team preserves context across asynchronous review.'] }, { heading: 'Analysis and decision boundary', body: ['Review capacity is a control only when the queue is visible and ownership is clear. Fast approval with no meaningful comments is not equivalent to a slower review that catches a defect. Inspect the oldest items and record why each waited. If the cause is unclear ownership, another reviewer may not help. If it is oversized changes, scope is the intervention.'] }, { heading: 'Limitations and conclusion', body: ['Repository history cannot measure an unrecorded discussion or prove that an escaped defect would have been caught. Labels may be inconsistent, and post-merge findings are imperfect. Set a local review boundary, retain the denominator, and assign an exception owner. The developer supplies a focused diff; the internal technical owner decides what risk may wait.'] }],
  'offshore-developer-test-flakiness-research-2026-08-17': [{ heading: 'Research question and scope', body: ['This report asks what repeated test failures mean when a distributed team works across machines, browsers, and dependencies. The unit is one test case observed across runs and revisions. NIST SSDF supports repeatable verification, while Google SRE treats unreliable signals as an operational cost. A rerun does not prove correctness. The question is whether the team can distinguish product, environment, and nondeterministic failures.'] }, { heading: 'Method and measurement', body: ['Record run count, pass rate, rerun recovery, failure clustering, duration, environment, and revision. Preserve the first failing log. Include the same case on a clean environment and under its normal failure conditions. The handoff should include the revision, fixture, and reproduction command so a reviewer in another time zone can test the claim.'] }, { heading: 'Analysis and decision boundary', body: ['A test becomes a risk when its failure teaches the team nothing. Quarantine can protect a delivery decision, but it creates uncovered behavior unless the owner records the gap and repair date. Compare quarantine duration with the path severity. A concurrency race needs different evidence from a clock-boundary failure. Decide whether to fix, isolate temporarily, or retire with explicit risk acceptance.'] }, { heading: 'Limitations and conclusion', body: ['Small samples miss rare races, and rerunning can change the timing that caused failure. This is not a controlled study of test suites. Keep the original failure, classify competing explanations, and require a reproducible next step. A developer can investigate and document the boundary; the technical owner decides whether uncertainty blocks release.'] }],
  'offshore-developer-migration-rollback-research-2026-08-17': [{ heading: 'Research question and scope', body: ['This report tests whether restoring application code also restores a changed data model. The unit is one schema change and its application compatibility window. NIST SSDF describes lifecycle practices for secure change, and Google SRE treats recovery as engineered capability. The question is whether old and new versions can coexist long enough to recover without losing writes or misreading data.'] }, { heading: 'Method and measurement', body: ['Scope evidence to representative data volume, migration duration, lock behavior, compatibility period, rollback time, and reconciliation result. Test forward, interrupted, and recovery paths with an approved restore procedure. Name schema and application revisions. The developer may implement the migration slice; the data owner decides acceptable loss, downtime, and forward-fix risk.'] }, { heading: 'Analysis and decision boundary', body: ['Expand-and-contract can reduce compatibility pressure while creating a period with two representations. A destructive column change has a different recovery problem from a nullable field. Measure writes during the compatibility window. If rollback cannot reverse valid writes, a forward fix may be safer than treating old code as complete recovery.'] }, { heading: 'Limitations and conclusion', body: ['Synthetic rehearsal cannot prove production recovery at every scale. Restore permissions and concurrent writes can differ. State what rollback restores, what it cannot restore, and who approves residual risk. Evidence should be reproducible and bounded, with no claim that one migration pattern fits every database.'] }],
  'offshore-developer-accessibility-defect-research-2026-08-17': [{ heading: 'Research question and scope', body: ['This report studies one user journey containing an accessibility defect and asks how impact and reproducibility should affect remediation priority. WCAG 2.2 defines testable criteria, but conformance language does not say whether a person can complete the current journey. The question for a distributed frontend team is whether evidence is specific enough for an internal release decision.'] }, { heading: 'Method and measurement', body: ['Record journey, browser, input method, assistive technology where relevant, affected control, expected result, observed result, and repeatability. Pair automated findings with keyboard and manual confirmation. Preserve reproduction and rendered evidence. The artifact can be reviewed asynchronously by a Philippines-based developer and an internal accessibility owner.'] }, { heading: 'Analysis and decision boundary', body: ['Prioritize a defect when it blocks a supported task, affects a meaningful cohort, or creates a state users cannot recover from. A cosmetic inconsistency needs a different threshold from an unfocusable control. Do not turn one screen-reader result into a claim about every technology. Test the declared combination and record its boundary.'] }, { heading: 'Limitations and conclusion', body: ['One ticket cannot estimate prevalence or establish legal compliance. Technology versions and user context vary. Make severity conditional on a named journey and observed barrier, then record supported and untested combinations. The contributor verifies the fix; the owner decides release priority and exceptions.'] }],
  'offshore-developer-api-error-taxonomy-research-2026-08-17': [{ heading: 'Research question and scope', body: ['This report studies one failure response and the client behavior it triggers. OWASP ASVS and NIST SSDF support explicit, testable security behavior, but neither prescribes one error vocabulary. The question is whether error classes help callers recover without exposing unstable implementation detail or encouraging unsafe retries.'] }, { heading: 'Method and measurement', body: ['Collect validation, authorization, conflict, dependency, and unexpected-failure cases. Record status, stable code, safe action, retry policy, correlation identifier, and telemetry. Include unknown-code behavior for older clients. A developer can add fixtures and client tests; the API owner decides which errors are public behavior.'] }, { heading: 'Analysis and decision boundary', body: ['A useful taxonomy maps to caller decisions, not every server exception. Validation may invite correction, conflict may require refresh, and dependency failure may be retryable only under a bounded policy. A generic 500 hides distinctions, while database details create risk. Test old clients against new responses.'] }, { heading: 'Limitations and conclusion', body: ['This synthesis does not measure error frequency or prove that naming improves support outcomes. Client behavior can still be wrong. Publish only distinctions callers can act on, test negative cases, and keep implementation detail private. The API owner sets compatibility; the developer supplies evidence.'] }],
  'offshore-developer-alert-ownership-research-2026-08-17': [{ heading: 'Research question and scope', body: ['This report examines one alert rule from signal generation through acknowledgement and resolution. Google SRE distinguishes actionable signals from noise, while NIST supports accountable control operation. The question is whether the alert protects a service objective or transfers uncertainty between time zones in a distributed team.'] }, { heading: 'Method and measurement', body: ['Measure firing count, repeat rate, acknowledgement time, escalation count, resolution time, and the fraction leading to action. Join observations to the service objective and owner rota. Inspect false positives and alerts without a reachable responder. A cross-time-zone handoff should state impact, evidence, safe next action, and the decision needing approval.'] }, { heading: 'Analysis and decision boundary', body: ['Paging thresholds should follow user or service consequence. A warning can belong on a dashboard; a page needs an owner who can act. Removing noise without checking the represented failure can create a blind spot, while retaining an ownerless page teaches people to ignore it. Test a recent incident-shaped trace.'] }, { heading: 'Limitations and conclusion', body: ['Alert history reflects staffing, traffic, and threshold changes. A short period cannot establish a stable false-positive rate, and a runbook does not prove response. Assign each alert a purpose, threshold, responder, and review date. The service owner accepts the operational boundary.'] }],
  'offshore-developer-feature-flag-cleanup-research-2026-08-17': [{ heading: 'Research question and scope', body: ['Feature-flag removal changes behavior; it is not housekeeping. This report studies one flag and its branches, cohorts, and configuration. GitHub controls and NIST SSDF support traceable change, but age alone does not prove deletion is safe. The question is when removal reduces complexity without removing recovery or a required audience boundary.'] }, { heading: 'Method and measurement', body: ['Inventory evaluation sites, exposure cohorts, defaults, branch count, telemetry, release history, and rollback assumptions. Check on, off, missing, and old-config states. Separate dead branches from active behavior. The developer prepares the inventory and focused change; the product owner confirms the cohort and business decision.'] }, { heading: 'Analysis and decision boundary', body: ['Age prompts investigation, not removal. A flag may be stale because an experiment ended or still guard a migration. Replacing it with static configuration can preserve a boundary or hide the same decision. Test the intended default and failed-release recovery path before deletion.'] }, { heading: 'Limitations and conclusion', body: ['Code search misses runtime configuration and external consumers, so global unused status cannot be proved. Connect removal to exposure evidence, a named decision, and recovery ownership. Remove only the bounded behavior supported by that evidence.'] }],
  'offshore-developer-vulnerability-remediation-research-2026-08-17': [{ heading: 'Research question and scope', body: ['A vulnerability score is a signal for investigation, not proof that a deployed application is exploitable. This report maps one dependency advisory to a runtime path. NIST SSDF, CISA Secure by Design, and GitHub dependency-review guidance support visible dependency risk. The question is whether reachability and compatibility justify upgrade, mitigation, or exception.'] }, { heading: 'Method and measurement', body: ['Record affected versions, dependency graph, runtime usage, exploit preconditions, deployed revision, patch result, tests, and controls. Distinguish a lockfile package from reachable deployed code. Keep advisory identifier and observation date. The handoff should state what was checked and what needs security-owner judgment.'] }, { heading: 'Analysis and decision boundary', body: ['Reachability can change urgency but does not erase a vulnerable component. An unavailable patch may require isolation or configuration change. A successful upgrade also needs compatibility evidence because remediation can cause an outage. Set a deadline from the affected path, not the severity label alone.'] }, { heading: 'Limitations and conclusion', body: ['Advisories change, graphs are imperfect, and tests cannot prove absence of every exploit condition. This is not a certification. Preserve the chain from advisory to runtime path to decision. The service or security owner approves exceptions and their expiry.'] }],
  'offshore-developer-documentation-drift-research-2026-08-17': [{ heading: 'Research question and scope', body: ['Documentation drift becomes a risk when a reader follows plausible instructions against a changed system. This report studies one procedure beside current code and environment. NIST SSDF and GitHub engineering guidance favor repeatable practice, but age alone does not show that a document is wrong. The question is whether a new reviewer can perform the intended task safely.'] }, { heading: 'Method and measurement', body: ['Compare prerequisites, commands, permissions, routes, configuration, output, and recovery advice with a current revision. Record walkthrough date, environment, failed steps, and missing assumptions. Include a normal run and a boundary case. A contributor can perform the comparison; the internal owner decides authority.'] }, { heading: 'Analysis and decision boundary', body: ['The strongest drift signal is a mismatch that changes a decision. A renamed command may be harmless; a removed permission step may be unsafe. Link corrections to code or policy, and mark untested claims. Do not hide an unavailable environment behind a polished rewrite.'] }, { heading: 'Limitations and conclusion', body: ['A clean walkthrough cannot represent every operator, version, or failure. A document can be correct for one deployment and wrong for another. State revision, environment, scope, and untested boundaries, then assign a recheck owner and trigger.'] }],
  'offshore-developer-code-ownership-research-2026-08-17': [{ heading: 'Research question and scope', body: ['Ownership files matter only when they lead to a reachable reviewer and understandable escalation. This report examines one repository area and recent review decisions. GitHub protected-branch documentation describes enforceable settings, while Google practice emphasizes judgment. The question is whether boundaries protect sensitive paths without creating a single-person bottleneck for asynchronous Philippines-based development.'] }, { heading: 'Method and measurement', body: ['Measure review coverage, owner-response time, rejected-scope changes, sensitive-path access, unavailable-owner cases, and unresolved escalations. Inspect the rule, actual response, and path changed. A name is not enough if the person cannot respond or lacks authority. Preserve urgent-work exceptions.'] }, { heading: 'Analysis and decision boundary', body: ['Good ownership separates consultation from approval. A developer may change a component while an internal security or product owner approves a sensitive decision. Broad ownership creates noise; narrow ownership creates workarounds. Test a representative change and unavailable-owner case.'] }, { heading: 'Limitations and conclusion', body: ['Settings do not capture every conversation, and a small sample cannot prove long-term delivery improvement. Map each sensitive area to a reachable reviewer, escalation path, and approval boundary. The developer preserves evidence; the accountable owner retains authority over access and risk.'] }],
};

export const researchPosts: readonly ResearchPost[] = dailyResearchTopics.map(([slug, title, cluster, evidence, sourceDate]) => ({
  slug,
  title,
  excerpt: `Research on ${title.toLowerCase()} for a distributed development team. The report turns ${cluster} evidence into a bounded operating routine with a named reviewer.`,
  published: sourceDate ?? '2026-08-09',
  sections: sourceDate === '2026-08-13' ? buildAugust13Sections(aug13ResearchDetails[slug], evidence) : sourceDate === '2026-08-14' ? buildAugust13Sections(aug14ResearchDetails[slug], evidence) : sourceDate === '2026-08-17' ? aug17IndependentBodies[slug] : [
    { heading: 'Methodology and scope', body: [`This report reviewed ${sourceBank.length} primary or standards-oriented sources and translated them into a practical checklist for ${cluster}. It separates what the sources say from recommendations for a buyer-side owner. The unit of analysis is one bounded work lane with a named reviewer and reproducible evidence.`] },
    { heading: 'Key finding', body: [`The useful signal is a reviewable result, not activity volume. For this topic, the evidence to request is ${evidence}. A written brief, focused verification, and explicit approval boundary reduce the cost of distributed ownership and make exceptions visible.`] },
    { heading: 'Operating model', body: ['Start with one representative task. State the acceptance check, permitted access, reviewer, and stop rule before work begins. Keep architecture decisions, security exceptions, production approvals, and accepted risk with the named internal owner.', 'At the end of the workday, record what changed, what passed, what remains, and who owns the next decision. Use UTC for durable technical events and local times only for scheduled overlap.'] },
    { heading: 'Limits and interpretation', body: ['This is a synthesis of published guidance, not a controlled experiment or a claim that one staffing model guarantees delivery. Context, system maturity, reviewer availability, and task complexity can change the result. Validate the recommendation with a small pilot and preserve the source links in the brief.'] },
  ],
  keyStats: sourceDate === '2026-08-13' || sourceDate === '2026-08-14' ? [`${sourceBank.length} authoritative sources reviewed`, '1 bounded unit with explicit cohort and observation period', '4 evidence categories: outcome, boundary, failure, and decision owner'] : sourceDate === '2026-08-17' ? [`${aug17ResearchDetails[slug].sources.length} claim-relevant authoritative sources`, '1 bounded unit with an explicit cohort or observation period', '4 evidence categories: outcome, boundary, counterevidence, and decision owner'] : [`${sourceBank.length} sources reviewed`, '4 evidence categories: outcome, verification, handoff, and unresolved risk', '1 named owner for exceptions and final approval'],
  takeaways: [`Ask for ${evidence}.`, 'Use a representative task with written acceptance criteria.', 'Grant only the access required for that task.', 'Review evidence before expanding scope.'],
  faqs: [
    { question: 'What should the reviewer accept?', answer: 'The reviewer should accept the stated outcome, the verification evidence, the handoff, and any explicitly documented limitation.' },
    { question: 'Can this routine replace technical leadership?', answer: 'No. It makes a bounded lane easier to review; architecture, security exceptions, production approval, and accepted risk remain with the internal owner.' },
  ],
  related: [
    { title: 'Developer first-week onboarding checklist', href: '/blog/offshore-developer-first-week-onboarding-checklist' },
    { title: 'Developer assessment guide', href: '/blog/hire-software-developers-philippines-assessment-guide' },
    { title: 'Research library', href: '/research' },
  ],
  sources: sourceDate === '2026-08-17' ? aug17ResearchDetails[slug].sources.map((sourceIndex) => ({ name: sourceBank[sourceIndex][0], url: sourceBank[sourceIndex][1] })) : sourceBank.map(([name, url]) => ({ name, url })),
}));
export const postsPerPage = 23;
const isFrozenAugust10Batch = (slug: string, date: string) => date === '2026-08-10' && /-(?:r2|run2)$/.test(slug);
export const compareNewestBatchFirst = (a: {slug: string}, b: {slug: string}, dateA: string, dateB: string) => {
  const byDate = dateB.localeCompare(dateA);
  if (byDate) return byDate;
  return Number(isFrozenAugust10Batch(b.slug, dateB)) - Number(isFrozenAugust10Batch(a.slug, dateA));
};
